<script lang="ts">import{gameCommands,gameState}from'$lib/application/game-store';import{INSECTS,FURNITURE,ACHIEVEMENTS}from'$lib/content/personalization';export let close:()=>void;let x=0,y=0;const petTypes=['cat','dog','horse'] as const;const furniture=Object.entries(FURNITURE) as Array<[keyof typeof FURNITURE,(typeof FURNITURE)[keyof typeof FURNITURE]]>;const insectName=(id:string)=>INSECTS[id as keyof typeof INSECTS].name;</script>
<div class="modal" role="dialog" aria-modal="true"><section><button class="close" on:click={close}>×</button><small>PERSONALISASI & KOLEKSI</small><h2>Rumah dan Sahabat</h2><h3>PETS & MOUNT</h3><div class="cards">{#each petTypes as type}<article><b>{type}</b>{#if $gameState.personalization.pets.find(p=>p.type===type)}<span>Friendship {$gameState.personalization.pets.find(p=>p.type===type)?.friendship}</span><button on:click={()=>gameCommands.pet(type)}>Interaksi</button>{:else}<button on:click={()=>gameCommands.adopt(type)}>Adopsi</button>{/if}</article>{/each}</div><button on:click={()=>gameCommands.mount()}>{$gameState.personalization.mounted?'Turun dari Kuda':'Naik Kuda'}</button>
<h3>BUG CATCHING</h3><button on:click={()=>gameCommands.spawnInsects()}>Cari Serangga</button><div class="cards">{#each $gameState.personalization.insectSpawns as insect}<article><b>{insectName(insect.type)}</b><button disabled={insect.caught} on:click={()=>gameCommands.catchInsect(insect.id)}>Tangkap</button></article>{/each}</div>
<h3>HOME CUSTOMIZATION</h3><label>X <input type="number" min="0" max="7" bind:value={x}></label><label>Y <input type="number" min="0" max="5" bind:value={y}></label><div class="cards">{#each furniture as [id,f]}<button on:click={()=>gameCommands.buyFurniture(id,x,y)}>{f.name} · {f.price}</button>{/each}</div>
<h3>ACHIEVEMENTS</h3><button on:click={()=>gameCommands.achievements()}>Periksa Pencapaian</button><ul>{#each ACHIEVEMENTS as a}<li class:done={$gameState.personalization.achievements.includes(a.id)}>{a.name} · {a.reward} koin</li>{/each}</ul><button on:click={()=>gameCommands.photoMode()}>Photo Mode</button></section></div>
<style>.modal{position:fixed;z-index:20;inset:0;background:#071a16dd;display:grid;place-items:center;padding:15px}section{position:relative;width:min(800px,100%);max-height:92vh;overflow:auto;padding:25px;background:#e8ddb8;color:#203c35;border:8px double #6e5037}.close{position:absolute;right:8px;top:6px;border:0;background:none;font-size:1.6rem}h2{font:900 2rem Georgia}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin:7px 0}.cards article{display:grid;gap:5px;padding:10px;background:#fff7d9;border:2px solid #927340}button{padding:7px;background:#315d4b;color:white;border:0;margin:3px}input{width:60px;padding:6px}.done{color:#39794f;font-weight:bold}@media(max-width:600px){.cards{grid-template-columns:1fr 1fr}}</style>
